            hE6.Dispose(); Tick();
            Check(ContentService.UnregisterDirectory(dirE) && Ref(OTHER_E) == 0 && ContentService.LiveAssetCount == live0E, $"⑧ released; Other unregisters; nothing left (live=+{ContentService.LiveAssetCount - live0E})");
