                bool ok3 = Get45(q3);
                Check(ok3 && Same45(System.IO.Path.Combine(Dir45(), first.File), b.files[first.File]) && FakeWeb.CountContaining(first.File + " range=bytes=3-") == 1 && FakeWeb.CountContaining(first.File + " range=-") == 1,
