            }

            // ── T16: a dropped connection resumes with Range · a server that ignores Range · an oversized .part ──
            Fresh45();
            {
                var b = Build45(); Serve45(b);
                var a0 = b.index.Archives[0];
                FakeWeb.Files[Base45 + "/" + a0.File].CutAfter = 1000;
                var r = Check45();
                bool ok = Get45(r);
